# --------------------------------- model ---------------------------------- #
def tmdl(name: str) -> str:
    return (MODEL / name).read_text(encoding="utf-8")


def test_relationships_star_schema():
    rel = tmdl("relationships.tmdl")
    pairs = re.findall(r"fromColumn: (\w+)\.(\w+)\n\ttoColumn: (\w+)\.(\w+)", rel)
    assert sorted(pairs) == sorted([
        ("monthly_long", "series_code", "dim_series", "series_code"),
        ("risk_summary", "series_code", "dim_series", "series_code"),
        ("yearly_real", "series_code", "dim_series", "series_code"),
        ("closure_summary", "series_code", "dim_series", "series_code"),
        ("monthly_long", "month", "dim_month", "month")])
    assert "crossFilteringBehavior" not in rel   # default = single direction
    assert "correlation_long" not in rel and "context" not in rel


def test_auto_date_time_off_and_no_local_date_tables():
    assert "annotation __PBI_TimeIntelligenceEnabled = 0" in tmdl("model.tmdl")
    assert not list((MODEL / "tables").glob("LocalDateTable*")) and "LocalDateTable" not in tmdl("model.tmdl")


def test_dim_month_sorting_and_keys():
    t = tmdl("tables/dim_month.tmdl")
    block = t[t.index("column month_label_fa"):t.index("column month_end_gregorian")]
    assert "sortByColumn: sort_key" in block
    month = t[t.index("column month\n"):t.index("column month_label_fa")]
    assert "isKey" in month
    assert "isKey" in tmdl("tables/dim_series.tmdl")


def test_percentage_columns_formatted():
    for t in ["monthly_long", "risk_summary", "yearly_real", "closure_summary", "context"]:
        for c in bd.table_columns(t):
            if c["dataType"] == "double" and c["name"] not in bd.NUM_FORMAT:
                assert c["format"] == bd.PCT, (t, c["name"])


def test_measures_in_measures_table_and_dax_file():
    required = ["CPI growth (×)", "Index real cum 3y", "Equal-weight real cum 3y",
                "Stocks beating inflation", "Closure real loss (pro-rated)", "Selected real CAGR",
                "Selected real vol", "Selected max drawdown", "Selected months beating inflation"]
    names = [m["name"] for m in bd.MEASURES]
    assert set(required) <= set(names)
    mt = tmdl("tables/_Measures.tmdl")
    dax = (DASH / "measures.dax").read_text(encoding="utf-8")
    for n in names:
        assert f"measure {bd.q(n)} =" in mt
        assert f"{bd.q(n)} =" in dax
    for t in (MODEL / "tables").glob("*.tmdl"):
        if t.stem != "_Measures":
            assert "\tmeasure " not in t.read_text(encoding="utf-8"), t.name
    pct_measures = [m for m in bd.MEASURES if m["format"] == bd.PCT]
    assert len(pct_measures) >= 20


def test_m_added_columns_match_python_equivalents():
    """The engine test model reproduces the Power Query added columns in Python."""
    for table, cols in bd.ADDED.items():
        df = bd.table_frame(table)
        for name, expr, _ in cols:
            for label in re.findall(r'then "([^"]+)"', expr) + re.findall(r'else "([^"]+)"', expr):
                assert label in set(df[name].astype(str)), (table, name, label)


# ---------------------- Power BI Desktop's own tools ---------------------- #
@needs_desktop
def test_tmdl_parses_with_power_bi_serializer():
    r = subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File",
                        str(DASH / "tools" / "check_tmdl.ps1"), str(MODEL)],
                       capture_output=True, text=True, encoding="utf-8", timeout=300)
    assert r.returncode == 0, r.stdout + r.stderr
    assert "table _Measures: 0 columns, %d measures" % len(bd.MEASURES) in r.stdout
    assert r.stdout.count("relationship ") == 5


def parse_results(path: Path) -> dict[int, pd.DataFrame]:
    out, cur, rows = {}, None, []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("## "):
            if cur is not None:
                out[cur] = rows
            cur, rows = int(line[3:]), []
        elif line:
            rows.append(line.split("\t"))
    out[cur] = rows
    frames = {}
    for k, r in out.items():
        assert not r[0][0].startswith("ERROR"), f"query {k}: {r[0][0]}"
        cols = [re.sub(r"^.*\[(.*)\]$", r"\1", c) for c in r[0]]
        frames[k] = pd.DataFrame(r[1:], columns=cols)
    return frames


def num(x):
    return float(x) if x not in ("", None) else float("nan")


@pytest.fixture(scope="module")
def engine(tmp_path_factory):
    if not DESKTOP.exists():
        pytest.skip("Power BI Desktop not installed")
    out = tmp_path_factory.mktemp("engine") / "results.tsv"
    r = subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File",
                        str(DASH / "tools" / "test_model_on_engine.ps1"), "-OutFile", str(out)],
                       capture_output=True, text=True, encoding="utf-8", timeout=600, cwd=ROOT)
    assert r.returncode == 0 and "refresh: OK" in r.stdout, r.stdout + r.stderr
    return parse_results(out)


def test_engine_headline_measures(engine):
    rs = pd.read_csv(PBI / "risk_summary.csv").set_index("code")
    cl = pd.read_csv(PBI / "closure_summary.csv").set_index(["series_code", "window"])
    for q in (1, 2):
        r = engine[q].iloc[0]
        assert num(r["cpi_growth_x"]) == pytest.approx(1 + rs.loc["cpi", "nominal_cum_3y"])
        assert num(r["index_real_cum_3y"]) == pytest.approx(rs.loc["index_total", "real_cum_3y"])
        assert r["stocks_beating"] == "3 از 8"
        assert num(r["closure_loss_prorated"]) == pytest.approx(cl.loc[("index_total", "on_reopening"), "real_prorated"])
    r = engine[1].iloc[0]
    assert num(r["ew_real_cum_3y"]) == pytest.approx(rs.loc["index_equal_weight", "real_cum_3y"])
    assert num(r["closure_loss_whole_months"]) == pytest.approx(cl.loc[("index_total", "on_reopening"), "real_whole_months"])


def test_engine_selected_series(engine):
    rs = pd.read_csv(PBI / "risk_summary.csv").set_index("code")
    for q, code, name in ((3, "index_total", "شاخص کل"), (4, "fameli", "فملی")):
        r = engine[q].iloc[0]
        assert r["code"] == code and r["name"] == name
        assert num(r["cagr"]) == pytest.approx(rs.loc[code, "real_cagr"])
        assert num(r["vol"]) == pytest.approx(rs.loc[code, "real_vol_per_year"])
        assert num(r["mdd"]) == pytest.approx(rs.loc[code, "real_max_drawdown_peak_to_trough"])
        assert num(r["months"]) == pytest.approx(rs.loc[code, "pct_months_beat_inflation"])
        assert num(r["cum"]) == pytest.approx(rs.loc[code, "real_cum_3y"])


def test_engine_series_tables(engine):
    rs = pd.read_csv(PBI / "risk_summary.csv").set_index("code")
    t = engine[5].set_index("series_code")
    assert set(t.index) == set(rs.index)
    for code in rs.index:
        assert num(t.loc[code, "real_cagr"]) == pytest.approx(rs.loc[code, "real_cagr"])
        assert num(t.loc[code, "nominal_cagr"]) == pytest.approx(rs.loc[code, "nominal_cagr"])
    ml = pd.read_csv(PBI / "monthly_long.csv").set_index(["series_code", "month"])
    g = engine[6]
    assert len(g) == 3 * 37
    for _, r in g.iterrows():
        exp = ml.loc[(r["series_code"], r["month"])]
        assert num(r["real_growth_index"]) == pytest.approx(exp["real_index_1402_06_eq_100"])
        if not pd.isna(exp["real_return_rolling_12m"]):
            assert num(r["rolling_12m"]) == pytest.approx(exp["real_return_rolling_12m"])
        else:
            assert r["rolling_12m"] == ""
    yr = pd.read_csv(PBI / "yearly_real.csv").set_index(["code", "block"])
    for _, r in engine[7].iterrows():
        assert num(r["real_return_per_year"]) == pytest.approx(yr.loc[(r["series_code"], r["block"]), "real_return_per_year"])


def test_engine_closure_context_counts(engine):
    cl = pd.read_csv(PBI / "closure_summary.csv").set_index(["series_code", "window"])
    for _, r in engine[8].iterrows():
        exp = cl.loc[(r["series_code"], r["window"])]
        assert num(r["nominal"]) == pytest.approx(exp["nominal"])
        assert num(r["cpi_prorated"]) == pytest.approx(exp["cpi_prorated"])
        if exp["comparable"]:
            assert num(r["real_prorated"]) == pytest.approx(exp["real_prorated"])
    ctx = pd.read_csv(PBI / "context.csv").iloc[0]
    r = engine[9].iloc[0]
    assert num(r["bond_ytm"]) == pytest.approx(ctx["bond_ytm"])
    assert num(r["real_avg"]) == pytest.approx(ctx["real_yield_avg"])
    assert "1405-07-22" in r["source"] and "-19%" in r["statement"] and "-26%" in r["statement"]
    c = engine[10].iloc[0]
    for t in ["dim_series", "dim_month", "monthly_long", "risk_summary", "yearly_real",
              "closure_summary", "correlation_long", "context"]:
        assert int(c[t]) == len(pd.read_csv(PBI / f"{t}.csv")), t
    assert c["unmatched_series"] in ("", "0") and c["unmatched_month"] in ("", "0")
    assert "sector_index" not in set(engine[12]["type"])


# ------------------------------ step-4 additions -------------------------- #
def _texts(visuals):
    out = []
    for v in visuals:
        if v["visual"]["visualType"] == "textbox":
            for para in v["visual"]["objects"]["general"][0]["properties"]["paragraphs"]:
                out.append("".join(r["value"] for r in para["textRuns"]))
    return out


def _page(name):
    return next(v for p, v in _pages() if p["displayName"] == name)


def test_every_page_has_subtitle_and_footer():
    for name in PAGE_NAMES:
        visuals = _page(name)
        texts = _texts(visuals)
        assert bd.FOOTER in texts, name
        sub = next(v for v in visuals if v["name"] == bd.hid("visual", bd.hid("page", {
            PAGE_NAMES[0]: "overview", PAGE_NAMES[1]: "dispersion",
            PAGE_NAMES[2]: "closure", PAGE_NAMES[3]: "timing"}[name]), "subtitle"))
        line = _texts([sub])[0]
        assert "\n" not in line and len(line) < 160 and any(c in line for c in "۰۱۲۳۴۵۶۷۸۹"), name
        foot = next(v for v in visuals if _texts([v]) == [bd.FOOTER]) if bd.FOOTER in texts else None
        assert foot["position"]["y"] + foot["position"]["height"] <= 720
    assert bd.FOOTER == "منبع: TSETMC و شاخص قیمت مصرف‌کننده مرکز آمار ایران (۱۴۰۰=۱۰۰)"


def test_no_visual_overlaps_footer_or_page_edge():
    for name in PAGE_NAMES:
        for v in _page(name):
            pos = v["position"]
            assert pos["x"] >= 0 and pos["x"] + pos["width"] <= 1280 + 0.5, (name, v["name"])
            if _texts([v]) != [bd.FOOTER]:
                assert pos["y"] + pos["height"] <= 690, (name, v["name"])


def test_page1_real_bars_sign_coloured_and_hindsight_note():
    visuals = _page(PAGE_NAMES[0])
    assert bd.HINDSIGHT_NOTE in _texts(visuals)
    assert bd.HINDSIGHT_NOTE == "۸ سهم با نگاه به گذشته انتخاب شده‌اند و نمایندهٔ کل بازار نیستند."
    bar = next(v for v in visuals if v["visual"]["visualType"] == "clusteredBarChart")
    dp = bar["visual"]["objects"]["dataPoint"]
    real = next(d for d in dp if d["selector"].get("metadata") == "_Measures.Real CAGR")
    assert real["properties"]["fill"]["solid"]["color"]["expr"]["Measure"]["Property"] == "Real CAGR color"
    dax = next(m for m in bd.MEASURES if m["name"] == "Real CAGR color")["dax"]
    assert any('"#2E7D32"' in x for x in dax) and any('"#C62828"' in x for x in dax)


def test_page2_block_matrix_diverging_on_zero():
    m = next(v for v in _page(PAGE_NAMES[1]) if v["visual"]["visualType"] == "pivotTable")
    qs = m["visual"]["query"]["queryState"]
    assert qs["Rows"]["projections"][0]["field"]["Column"]["Property"] == "series_fa"
    assert qs["Columns"]["projections"][0]["field"]["Column"]["Property"] == "block_fa"
    rule = m["visual"]["objects"]["values"][0]["properties"]["backColor"]["solid"]["color"]["expr"]["FillRule"]
    g = rule["FillRule"]["linearGradient3"]
    assert g["min"]["color"]["Literal"]["Value"] == "'#C62828'"
    assert g["mid"]["color"]["Literal"]["Value"] == "'#FFFFFF'" and g["mid"]["value"]["Literal"]["Value"] == "0D"
    assert g["max"]["color"]["Literal"]["Value"] == "'#2E7D32'"


def test_page4_rolling_with_zero_line_and_correlation_heatmap():
    visuals = _page(PAGE_NAMES[3])
    line = next(v for v in visuals if v["visual"]["visualType"] == "lineChart")
    assert line["visual"]["query"]["queryState"]["Y"]["projections"][0]["field"]["Measure"]["Property"] == "Real return rolling 12m"
    ref = line["visual"]["objects"]["y1AxisReferenceLine"][0]["properties"]
    assert ref["value"]["expr"]["Literal"]["Value"] == "0D"
    assert _filter_values(line["filterConfig"]["filters"][0]) == ["market_index"]
    heat = next(v for v in visuals if v["visual"]["visualType"] == "pivotTable")
    assert "FillRule" in heat["visual"]["objects"]["values"][0]["properties"]["backColor"]["solid"]["color"]["expr"]
    corr = pd.read_csv(PBI / "correlation_long.csv")
    assert len(corr) == 100 and corr["series_a_code"].nunique() == 10
    assert {"index_total", "index_equal_weight"} <= set(corr["series_a_code"])


def test_theme_blue_green_red_segoe():
    th = json.loads((DASH / "theme.json").read_text(encoding="utf-8"))
    reg = json.loads((REPORT / "StaticResources" / "RegisteredResources" / bd.CUSTOM_THEME).read_text(encoding="utf-8"))
